/// Parse a CSV string into rows of strings.
/// If skip_header is true, the first row is omitted from results.
pub fn parse_csv(input: &str, delimiter: char, skip_header: bool) -> Vec<Vec<String>> {
    let mut rows: Vec<Vec<String>> = input
        .lines()
        .filter(|l| !l.trim().is_empty())
        .map(|line| {
            // BUG 1: splits on ',' always instead of the given delimiter
            line.split(',')
                .map(|s| s.trim().to_string())
                .collect()
        })
        .collect();

    if skip_header {
        // BUG 2: removes the LAST row instead of the first
        rows.pop();
    }
    rows
}

/// Parse a row of strings as integers, skipping non-numeric values.
pub fn row_to_ints(row: &[String]) -> Vec<i64> {
    row.iter()
        .filter_map(|s| {
            // BUG 3: parses as u32 which can't handle negatives or large numbers
            s.parse::<u32>().ok().map(|n| n as i64)
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_csv_comma() {
        let result = parse_csv("a,b,c\n1,2,3", ',', false);
        assert_eq!(result.len(), 2);
        assert_eq!(result[0], vec!["a", "b", "c"]);
        assert_eq!(result[1], vec!["1", "2", "3"]);
    }

    #[test]
    fn test_parse_csv_pipe_delimiter() {
        let result = parse_csv("x|y|z\n4|5|6", '|', false);
        assert_eq!(result.len(), 2);
        assert_eq!(result[0], vec!["x", "y", "z"]);
    }

    #[test]
    fn test_skip_header_removes_first() {
        let result = parse_csv("name,age\nalice,30\nbob,25", ',', true);
        assert_eq!(result.len(), 2);
        assert_eq!(result[0], vec!["alice", "30"]);
        assert_eq!(result[1], vec!["bob", "25"]);
    }

    #[test]
    fn test_row_to_ints_negatives() {
        let row: Vec<String> = vec!["-5".to_string(), "10".to_string(), "abc".to_string()];
        let result = row_to_ints(&row);
        assert_eq!(result, vec![-5, 10]);
    }
}
